import { randomUUID } from 'node:crypto';
import { Inject, Injectable } from '@nestjs/common';
import type { NextFunction, Request, Response } from 'express';
import { JsonLogger, requestContext, safeRequestMetadata } from './json-logger.js';

declare module 'express' {
  interface Request {
    requestId?: string;
  }
}

@Injectable()
export class RequestTelemetry {
  constructor(@Inject(JsonLogger) private readonly logger: JsonLogger) {}
  handle = (request: Request, response: Response, next: NextFunction) => {
    // Correlation IDs are generated by the server; inbound headers cannot forge them.
    request.requestId = randomUUID();
    response.setHeader('X-Request-Id', request.requestId);
    response.setHeader('Cache-Control', 'no-store');
    const start = performance.now();
    let recorded = false;
    const complete = (outcome: 'finished' | 'aborted') => {
      if (recorded) return;
      recorded = true;
      const event = {
        event: 'request.completed',
        ...safeRequestMetadata(request),
        statusCode: response.statusCode,
        durationMs: Math.round((performance.now() - start) * 100) / 100,
        outcome,
      };
      if (response.statusCode >= 500) this.logger.error(event);
      else if (response.statusCode >= 400 || outcome === 'aborted') this.logger.warn(event);
      else this.logger.log(event);
    };
    response.once('finish', () => complete('finished'));
    response.once('close', () => {
      if (!response.writableFinished) complete('aborted');
    });
    requestContext.run({ requestId: request.requestId }, next);
  };
}
